{"implementation": "def solve(case):
    # Validate required fields
    if 'segments' not in case or 'budget' not in case:
        raise ValueError('Missing required fields: segments and budget')
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('segments must be a non-empty list')

    # Validate each segment and collect initial allocations
    n = len(segments)
    allocations = [0] * n
    for i, seg in enumerate(segments):
        if not all(k in seg for k in ('name', 'importance', 'minimum', 'capacity')):
            raise ValueError(f'Segment {i} missing required keys')
        min_val = int(seg['minimum'])
        cap_val = int(seg['capacity'])
        if min_val < 0 or cap_val < 0:
            raise ValueError(f'Segment {i} has negative minimum or capacity')
        if min_val > cap_val:
            raise ValueError(f'Segment {i} minimum exceeds capacity')
        allocations[i] = min_val

    min_sum = sum(allocations)
    capacity_sum = sum(int(seg['capacity']) for seg in segments)
    if budget < min_sum or budget > capacity_sum:
        raise ValueError(f'Budget {budget} out of range [{min_sum}, {capacity_sum}]')

    remaining = budget - min_sum
    # Greedy allocation
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if allocations[i] >= int(seg['capacity']):
                continue
            # score = importance / (next allocated position)
            # next position = allocations[i] + 1 (1-indexed)
            score = seg['importance'] / (allocations[i] + 1)
            if score > best_score:
                best_score = score
                best_idx = i
            elif score == best_score and best_idx == -1:
                # tie: original order -> first encountered wins because we iterate in order
                # but if best_idx already set and equal, we keep lower index (already earlier)
                pass
        if best_idx == -1:
            # No available capacity; should not happen if budget valid
            raise ValueError('Budget cannot be allocated due to capacity constraints')
        allocations[best_idx] += 1
        remaining -= 1

    total = sum(allocations)
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': total
    }
"}
